// But setup steps like "the app is loaded with no existing todos" and assertion steps
// like "the todo count shows {string}" don't planked seams — they go through harness only.
// The plank join should flag any step whose pattern is not planked on any seam.
for (const pattern of uncoveredPatterns) {
  // Skip common harness-only steps
  if (pattern === 'the app is loaded with no existing todos') continue;
  if (pattern === 'the file {string} is read') continue;
  if (pattern === 'the implementation directories are scanned for {string}') continue;
  // Flag it
  violations.push(`UNPLANKED_STEP: pattern "${pattern}" has no matching @planks or @planks-provisional on any seam`);
}

// --- Report ---
if (violations.length === 0) {
  console.log('plank-join: clean — ' + planks.length + ' planks, ' + provisionals.length + ' provisionals, ' + stepPatterns.length + ' step patterns, ' + captainScenarios.length + ' @captain scenarios');
  process.exit(0);
} else {
  console.error('plank-join: ' + violations.length + ' violation(s):');
  for (const v of violations) {
    console.error('  ' + v);
  }
  process.exit(1);
}

